/bin/bash -c "python - <<'PY'
from PIL import Image
import numpy as np
for name in ['first_frame.png','frames/10.png','frames/19.png']:
    a=np.array(Image.open(name).convert('RGB'))
    print(name, a.shape, 'mean', a.mean((0,1)).round(2), 'std', a.std((0,1)).round(2))
    for y in [0,20,40,58,62,70,80,90,92,100,110,120,130,137,143]:
        row=a[y]
        # run-length rough colors quantized to 32 levels
        q=(row//32)
        runs=[]; s=0
        for x in range(1,256):
            if not np.array_equal(q[x],q[s]):
                if x-s>=5: runs.append((s,x-1,tuple(int(v) for v in row[(s+x-1)//2])))
                s=x
        if 256-s>=5: runs.append((s,255,tuple(int(v) for v in row[(s+255)//2])))
        print(' y',y, runs[:14])
    print()
PY"
